package ec.edu.monster.modelo;
public class CuentaResumen { private String codigoCuenta,moneda,estado,codigoCliente,nombreCliente; private double saldo; public String getCodigoCuenta(){return codigoCuenta;} public void setCodigoCuenta(String v){codigoCuenta=v;} public String getMoneda(){return moneda;} public void setMoneda(String v){moneda=v;} public double getSaldo(){return saldo;} public void setSaldo(double v){saldo=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} public String getCodigoCliente(){return codigoCliente;} public void setCodigoCliente(String v){codigoCliente=v;} public String getNombreCliente(){return nombreCliente;} public void setNombreCliente(String v){nombreCliente=v;} }
